// Orca forks this module in a Node worker on the desktop host and calls activate once. Orca starts it
// for a command, an event, or the panel's first plugin.request, and stops it after 5 idle minutes;
// the panel's next request starts it again.
import { connectionNotice, connectionReport } from './doctor.mjs'
import { createPanelData } from './panel.mjs'
import { collectSnapshot } from './snapshot.mjs'

// Entire writes its checkpoint data as an agent stops, so let it settle before reading.
const AGENT_SETTLE_MS = 3000

export default function activate(orca) {
  const notify = (notice, signal) =>
    orca.host.call('notifications.show', notice, { signal }).catch((error) => {
      console.error(`Notification failed: ${error.message}`)
    })

  // Tells open panels to ask for the data again. A post carries at most 256 KiB, so the data
  // itself goes back through the panel's request.
  const announce = () => {
    try {
      orca.panels?.post('entire.changed', {})
    } catch (error) {
      console.error(`Posting to the panel failed: ${error.message}`)
    }
  }

  // Each snapshot's report also goes to the plugin's Logs, since the command palette drops a
  // command's result.
  const collect = async (signal) => {
    const snapshot = await collectSnapshot(orca, { signal })
    console.log(connectionReport(orca, snapshot))
    return snapshot
  }

  // Only a read that found the workspace changed the data; a post after one that didn't would have the
  // panel fetch the old data and take it as news.
  const announceIfAdded = (snapshot) => {
    if (snapshot.workspace) announce()
    return snapshot
  }

  const panel = createPanelData({
    collect: () => collect().then(announceIfAdded),
    readContext: () => orca.host.call('workspace.readContext', {})
  })

  orca.panels?.handle('entire.data', async () => panel.data)
  orca.panels?.handle('entire.read', async (input) => panel.read({ maxAgeMs: Math.max(0, Number(input?.maxAgeMs) || 0) }))

  // A command must answer within 30 seconds, so it reads on its own, under its own signal.
  async function refresh(signal) {
    const snapshot = announceIfAdded(panel.add(await collect(signal)))
    return connectionReport(orca, snapshot)
  }

  orca.commands.register('doctor', async (_args, { signal }) => {
    const report = await refresh(signal)
    await notify(connectionNotice(report), signal)
    return report
  })

  orca.commands.register('refresh', async (_args, { signal }) => {
    const report = await refresh(signal)
    const notice = connectionNotice(report)
    if (notice.title !== 'Entire: connected') await notify({ ...notice, title: 'Entire: panel updated with a problem' }, signal)
    return 'Panel updated'
  })

  // An agent finishing is when Entire has new checkpoints and sessions to show. Several finishing
  // together make one read.
  let timer = null
  orca.events.on('agent.status.changed', (event) => {
    if ((event.mainAgent?.state ?? event.state) !== 'done') return
    clearTimeout(timer)
    timer = setTimeout(() => {
      timer = null
      panel.readAgain().catch((error) => console.error(`Refresh failed: ${error.message}`))
    }, AGENT_SETTLE_MS)
  })
}
// What the panel shows of a trail, from `entire trail show --json` and `entire trail finding list --json`
// (shapes in test/fixtures/trail-*.json): the change this branch is, its merge gates and review, and
// its open findings. Entire's text is untrusted; the panel renders it as text only.
const BODY_LIMIT = 400
const FINDING_LIMIT = 20
const TEXT_LIMIT = 200
const LIST_LIMIT = 30

export function trailSummary(trail, { findings = null, diff = null } = {}) {
  const changes = Array.isArray(trail.changes) ? trail.changes : []
  const current = changes.find((change) => change.current) ?? changes.find((change) => change.mergeability) ?? null
  const about = findings?.trail ?? {}
  return {
    number: trail.number ?? null,
    title: trail.title ?? '',
    status: trail.status ?? null,
    type: trail.type ?? null,
    priority: trail.priority && trail.priority !== 'none' ? trail.priority : null,
    body: typeof trail.body === 'string' ? trail.body.slice(0, BODY_LIMIT) : '',
    repository: current?.repository ?? null,
    change: current?.number ?? null,
    changeStatus: current?.status ?? null,
    branch: current?.branch ?? about.branch ?? null,
    base: about.base ?? null,
    author: about.author?.login ?? null,
    createdAt: trail.createdAt ?? null,
    mergedAt: about.mergedAt ?? null,
    diff,
    changes: changes.map((change) => ({
      repository: change.repository ?? '',
      branch: change.branch ?? '',
      status: change.status ?? null,
      current: change === current
    })),
    merge: current?.mergeability ? mergeSummary(current.mergeability, about.base) : null,
    findings: findings ? findingsSummary(findings) : null
  }
}

function mergeSummary(mergeability, base) {
  const gates = mergeability.gates ?? []
  const findingsGate = gates.find((gate) => gate.gate_type === 'findings')
  return {
    mergeable: Boolean(mergeability.mergeable),
    conflicts: mergeability.conflict_status && !['clean', 'unknown'].includes(mergeability.conflict_status) ? mergeability.conflict_status : null,
    gates: gates.map((gate) => ({
      key: gate.gate_key ?? gate.gate_type ?? 'gate',
      type: gate.gate_type ?? null,
      blocking: Boolean(gate.blocking),
      status: gate.status ?? 'unknown',
      evaluated: gate.state !== 'not_run',
      rationale: text(gate.rationale),
      summary: gateSummary(gate, base),
      people: gate.gate_type === 'approvals' ? approvers(gate) : [],
      at: gate.completed_at ?? null,
      sha: gate.evaluated_at_sha ? String(gate.evaluated_at_sha).slice(0, 7) : null,
      // Evaluated on an earlier commit than the change's head.
      outdated: Boolean(gate.evaluated_at_sha && gate.head_sha && gate.evaluated_at_sha !== gate.head_sha),
      staleReason: gate.stale_reason ? text(gate.stale_reason) : null,
      detail: gateDetail(gate, mergeability)
    })),
    review: findingsGate ? reviewSummary(findingsGate) : null
  }
}

function text(value) {
  return String(value ?? '').slice(0, TEXT_LIMIT)
}

// What the panel shows when a gate is opened: who approved, each check run, the review behind the
// findings gate, or how far behind the base the branch is.
function gateDetail(gate, mergeability) {
  const value = gate.value ?? {}
  const config = value.config ?? {}
  if (gate.gate_type === 'approvals') {
    return {
      approved: value.approved ?? 0,
      required: value.required ?? config.min_reviewers ?? 0,
      changesRequested: Boolean(value.changes_requested),
      staleDismissed: value.stale_dismissed ?? 0,
      selfExcluded: Boolean(value.self_excluded),
      selfApproval: config.allow_self_approval ?? null,
      dismissStale: config.dismiss_stale_approvals_on_push ?? null,
      reviewers: gateReviewers(gate)
    }
  }
  if (gate.gate_type === 'checks') {
    // The change's own runs carry the app and timing; the gate's copy is the fallback.
    const runs = mergeability.checks?.runs?.length ? mergeability.checks.runs : (value.checks ?? [])
    return {
      requireAll: config.require_all_success ?? null,
      required: (config.required_checks ?? []).slice(0, LIST_LIMIT).map((check) => text(check?.name ?? check)),
      total: value.total_count ?? runs.length,
      runs: runs.slice(0, LIST_LIMIT).map((run) => ({
        name: text(run.name ?? 'check'),
        app: run.app_name ? text(run.app_name) : null,
        status: run.conclusion ?? run.status ?? 'unknown',
        startedAt: run.started_at ?? null,
        completedAt: run.completed_at ?? null
      }))
    }
  }
  if (gate.gate_type === 'findings') {
    if (gate.state === 'not_run' || !gate.value) return null
    const review = reviewSummary(gate)
    return {
      minSeverity: config.agent_findings_min_severity ?? null,
      blocking: value.agent_blocking_findings ?? gate.finding_count ?? 0,
      reviewedHead: value.reviewed_head ?? null,
      inFlight: review.inFlight,
      reviewers: review.reviewers.slice(0, LIST_LIMIT),
      severity: review.severity
    }
  }
  if (gate.gate_type === 'up_to_date') {
    if (gate.state === 'not_run' || !gate.value) return null
    return {
      behindBy: value.behind_by ?? 0,
      compare: value.compare_status ?? null,
      allowBehind: config.allow_behind_if_mergeable ?? null
    }
  }
  return null
}

// Everyone who reviewed, once each, with where they landed.
function gateReviewers(gate) {
  const seen = new Set()
  return [gate.reviewers, gate.value?.reviewers]
    .flat()
    .filter((reviewer) => reviewer?.login && !seen.has(reviewer.login) && seen.add(reviewer.login))
    .slice(0, LIST_LIMIT)
    .map((reviewer) => ({
      login: text(reviewer.login),
      state: reviewer.state ?? 'unknown',
      reason: reviewer.reason ? text(reviewer.reason) : null,
      outdated: Boolean(reviewer.reviewed_head_sha && gate.head_sha && reviewer.reviewed_head_sha !== gate.head_sha)
    }))
}

// The short phrase Entire's web view puts beside each gate, such as "2 of 2 passed".
function gateSummary(gate, base) {
  const value = gate.value ?? {}
  if (gate.state === 'not_run') return 'Not evaluated yet'
  if (gate.gate_type === 'approvals') return `${value.approved ?? 0} of ${value.required ?? 0}`
  if (gate.gate_type === 'checks') {
    const runs = value.checks ?? []
    const total = value.total_count ?? runs.length
    if (!total) return 'No checks'
    return `${runs.filter((run) => run.conclusion === 'success').length} of ${total} passed`
  }
  if (gate.gate_type === 'findings') {
    const blocking = value.agent_blocking_findings ?? gate.finding_count ?? 0
    return blocking ? `${blocking} blocking` : 'None blocking'
  }
  if (gate.gate_type === 'up_to_date' && value.behind_by > 0) return `${value.behind_by} behind ${base ?? 'base'}`
  return null
}

function approvers(gate) {
  const reviewers = [gate.reviewers, gate.value?.reviewers].flat().filter(Boolean)
  return reviewers.filter((reviewer) => reviewer.state === 'approved' && reviewer.login).map((reviewer) => reviewer.login)
}

// The findings gate carries the review: which reviewers ran and what they found, by severity.
function reviewSummary(gate) {
  const value = gate.value ?? {}
  const reviewers = (value.reviewers ?? []).map((reviewer) => ({
    name: reviewer.name ?? 'Reviewer',
    kind: reviewer.kind ?? null,
    status: reviewer.status ?? 'unknown',
    blocking: reviewer.blocking_findings ?? 0,
    nonBlocking: reviewer.non_blocking_findings ?? 0
  }))
  return {
    status: gate.status ?? 'unknown',
    verdict: reviewVerdict(value, reviewers),
    inFlight: Boolean(value.review_in_flight),
    reviewers,
    severity: {
      high: value.agent_findings?.high ?? 0,
      medium: value.agent_findings?.medium ?? 0,
      low: value.agent_findings?.low ?? 0
    }
  }
}

const SEVERITY_ORDER = { high: 0, medium: 1, low: 2 }

// Open findings first, then by severity, as the web view lists them.
// A review agent's signal is true, a fail in Entire's web view, when it reports any defect, blocking
// or not. The findings gate is a separate question: it fails only on findings at its minimum severity.
function reviewVerdict(value, reviewers) {
  if (value.review_in_flight) return 'running'
  const done = reviewers.filter((reviewer) => reviewer.status === 'completed')
  if (!done.length) return 'not_run'
  return done.some((reviewer) => reviewer.blocking + reviewer.nonBlocking > 0) ? 'fail' : 'pass'
}

function findingsSummary({ counts = {}, findings = [] }) {
  const ordered = [...findings].sort(
    (a, b) => (a.status === 'open' ? 0 : 1) - (b.status === 'open' ? 0 : 1) || (SEVERITY_ORDER[a.severity] ?? 3) - (SEVERITY_ORDER[b.severity] ?? 3)
  )
  return {
    open: counts.Open ?? 0,
    high: counts.OpenHigh ?? 0,
    medium: counts.OpenMedium ?? 0,
    low: counts.OpenLow ?? 0,
    resolved: counts.Resolved ?? 0,
    dismissed: counts.Dismissed ?? 0,
    stale: counts.Stale ?? 0,
    items: ordered.slice(0, FINDING_LIMIT).map((finding) => {
      const location = finding.location ?? {}
      const body = String(finding.body ?? '')
      return {
        // Agents often leave the title empty and lead the body with the defect.
        title: (finding.title || body.split(/(?<=[.!?])\s|\n/)[0] || '').slice(0, TEXT_LIMIT),
        body: body.slice(0, BODY_LIMIT * 2),
        severity: finding.severity ?? null,
        confidence: typeof finding.confidence === 'number' ? finding.confidence : null,
        status: finding.status ?? null,
        reason: finding.statusReason ? String(finding.statusReason).slice(0, BODY_LIMIT) : null,
        stale: finding.staleOutcome === 'stale',
        file: location.filePath ?? location.file_path ?? null,
        line: location.startLine ?? location.start_line ?? null,
        endLine: location.endLine ?? location.end_line ?? null
      }
    })
  }
}
// What the panel shows: the newest snapshot of each workspace the worker read, kept in the worker's
// memory. The panel asks for it with plugin.request (the handlers are in main.mjs) and gets all of
// it, then picks the focused workspace's entry itself (findEntry in panel/index.html).
import { reportLines } from './doctor.mjs'

const MAX_WORKSPACES = 10
// Orca refuses a plugin.request answer over 1 MiB; leave room for its envelope.
const MAX_ANSWER_CHARS = 900_000

export function panelEntry(snapshot) {
  return { ...snapshot, report: reportLines(snapshot) }
}

// Same path on the same host, or a terminal they share.
function sameWorkspace(entry, other) {
  const environment = (e) => e.workspace.server?.environment ?? null
  return (
    (entry.workspace.path && other.workspace.path === entry.workspace.path && environment(other) === environment(entry)) ||
    other.workspace.terminals.some((id) => entry.workspace.terminals.includes(id)) ||
    (!other.workspace.path && other.workspace.name === entry.workspace.name && other.workspace.branch === entry.workspace.branch)
  )
}

// A newer entry replaces any for the same workspace, and the oldest go once the answer gets too big.
export function mergeEntry(data, entry, { maxChars = MAX_ANSWER_CHARS } = {}) {
  const others = (data?.workspaces ?? []).filter((other) => !sameWorkspace(entry, other))
  const workspaces = [entry, ...others].slice(0, MAX_WORKSPACES)
  while (workspaces.length > 1 && JSON.stringify(workspaces).length > maxChars) workspaces.pop()
  return { version: 1, workspaces }
}

// The entry the panel shows for a readContext result. Keep this the same as findEntry in
// panel/index.html: the worker uses it to tell whether the panel's entry is fresh enough.
export function findShown(data, context) {
  const list = data?.workspaces ?? []
  const ids = context.terminals.map((terminal) => terminal.id)
  // A workspace keeps its terminals when it switches branch, so the branch has to match as well.
  const byTerminal = list.find((entry) => entry.workspace.branch === context.branch && entry.workspace.terminals.some((id) => ids.includes(id)))
  if (byTerminal) return byTerminal
  // Many repos share a name and branch such as main/main: only when terminals can't tell them apart
  // and exactly one entry matches.
  const byName = list.filter(
    (entry) =>
      !(ids.length > 0 && entry.workspace.terminals.length > 0) && entry.workspace.name === context.displayName && entry.workspace.branch === context.branch
  )
  return byName.length === 1 ? byName[0] : null
}

// The panel's data and the reads that fill it. `collect` reads Entire for the focused workspace (a
// snapshot), `readContext` asks Orca which workspace that is. One read runs at a time: a request
// that finds one running waits for it, and reads again only if focus moved meanwhile.
export function createPanelData({ collect, readContext, now = Date.now }) {
  let data = null
  let reading = null

  function add(snapshot) {
    if (snapshot.workspace) data = mergeEntry(data, panelEntry(snapshot))
    return snapshot
  }

  // A read outlives the request that started it, since others may be waiting on it, so it takes no
  // signal; Entire's own timeouts bound it.
  function readNow() {
    reading ??= collect().then(add).finally(() => {
      reading = null
    })
    return reading
  }

  // A read that couldn't find the focused workspace (its lookup failed) added nothing, so answering
  // with the data would pass the old data off as this read's. Fail instead: the panel shows why and
  // retries on its schedule.
  async function readFresh() {
    const snapshot = await readNow()
    if (!snapshot.workspace) throw new Error(snapshot.problem ?? 'Entire was read for no workspace')
    return data
  }

  async function shown() {
    const context = await readContext()
    return context ? findShown(data, context) : null
  }

  return {
    get data() {
      return data
    },
    add,
    // Reads Entire unless the panel's entry for the focused workspace is younger than maxAgeMs (0
    // always reads), and answers with all the data.
    async read({ maxAgeMs = 0 } = {}) {
      if (maxAgeMs > 0) {
        const at = Date.parse((await shown())?.at)
        if (Number.isFinite(at) && now() - at < maxAgeMs) return data
      }
      if (reading) {
        const joined = await reading.catch(() => null)
        if (joined && (await shown())?.at === joined.at) return data
      }
      return readFresh()
    },
    // Reads Entire with a read that starts now: one already running may have begun before what the
    // caller wants to see, such as an agent's last checkpoint, so it waits for that one and reads again.
    async readAgain() {
      if (reading) await reading.catch(() => null)
      return readFresh()
    }
  }
}
import { entireCommand } from './hosts.mjs'
import { desktopEnv, run } from './process.mjs'

export function runEntire(host, args, { signal, timeoutMs } = {}) {
  const { command, args: argv, cwd } = entireCommand(host, args)
  return run(command, argv, { cwd, env: entireEnv(), signal, timeoutMs })
}

// Entire sends usage analytics from a detached `entire __send_analytics` child. On Windows that child has
// no console, so every git it runs opens a terminal window. The plugin's calls are background reads, so
// they opt out of analytics; WSLENV carries the opt-out into WSL as well.
export function entireEnv(env = desktopEnv()) {
  return {
    ...env,
    ENTIRE_TELEMETRY_OPTOUT: '1',
    WSLENV: env.WSLENV ? `${env.WSLENV}:ENTIRE_TELEMETRY_OPTOUT` : 'ENTIRE_TELEMETRY_OPTOUT'
  }
}

// Entire explains a failure in one line, on stderr or stdout depending on the command.
export function failureLine(result) {
  if (result.timedOut) return `timed out after ${result.ms} ms`
  return (result.stderr.trim() || result.stdout.trim() || `exit ${result.code}`).split('\n')[0]
}
import { failureLine, runEntire } from './entire-cli.mjs'
import { diffStat, safeRef } from './git.mjs'
import { serverHost, workspaceHost } from './hosts.mjs'
import { serverSshTarget } from './ssh-targets.mjs'
import { trailSummary } from './trail.mjs'
import { resolveFocusedWorkspace } from './workspace.mjs'

const VERSION = { key: 'version', label: 'Entire CLI', args: ['--version'], parse: (out) => out.trim().split('\n')[0] }

// Each step keeps its own outcome, so one failed call (a branch without a trail, say) hides nothing else.
// `byRepo` steps read Entire's server and also work for a paired server's workspace, given --repo and
// --branch; the others read the checkout, which for a paired server means over SSH.
const STEPS = [
  {
    key: 'status',
    label: 'Repo',
    args: ['status', '--json'],
    parse: JSON.parse,
    summarize: (status) =>
      status.enabled ? `enabled · agents: ${(status.agents ?? []).join(', ') || 'none'}` : 'Entire is not enabled here'
  },
  // A branch without a trail is normal, so this step reports instead of failing the check.
  {
    key: 'trail',
    label: 'Trail',
    args: ['trail', 'show', '--json'],
    byRepo: true,
    optional: true,
    parse: JSON.parse,
    summarize: (trail) => `#${trail.number} ${trail.title} · ${trail.status}`
  },
  {
    key: 'checkpoints',
    label: 'Checkpoints',
    args: ['checkpoint', 'list', '--json'],
    parse: JSON.parse,
    summarize: (list) => `${list.length} on this branch`
  }
]

// Fetched alongside the steps for the panel only: the connection check doesn't report them. Every status,
// so resolved findings and how they were fixed show too, as in Entire's web view.
const FINDINGS = {
  key: 'findings',
  label: 'Findings',
  args: ['trail', 'finding', 'list', '--status', 'any', '--freshness', 'any', '--json'],
  byRepo: true,
  parse: JSON.parse
}

// The panel keeps the newest checkpoints only.
const CHECKPOINT_LIMIT = 20

// Everything the panel and "Entire: Check connection" show for the focused workspace.
export async function collectSnapshot(orca, { signal } = {}) {
  const snapshot = { at: new Date().toISOString(), workspace: null, problem: null, steps: [], data: {} }

  let resolved
  try {
    resolved = await resolveFocusedWorkspace(orca, { signal })
  } catch (error) {
    return { ...snapshot, problem: `Workspace lookup failed: ${error.message}` }
  }
  const { context, path, via, candidates, server, unreachable = [] } = resolved
  if (!context) return { ...snapshot, problem: 'No workspace is focused' }
  const workspace = {
    name: context.displayName,
    branch: context.branch,
    terminals: context.terminals.map((terminal) => terminal.id),
    path,
    via
  }
  if (!path) return { ...snapshot, workspace, problem: unresolved(context, via, candidates, unreachable) }

  let host = workspaceHost(path)
  if (server) {
    let target = null
    let remoteProblem = null
    try {
      target = await serverSshTarget(server.environment, { signal })
    } catch (error) {
      remoteProblem = error.message
    }
    host = serverHost({ ...server, path, target, remoteProblem })
    // readContext gives a server workspace's repo name and no branch; the panel shows the real branch.
    workspace.server = { environment: server.environment, branch: server.branch }
    workspace.where = `${server.environment} ${path}`
    if (!host.repo) return { ...snapshot, workspace, problem: `${path} on ${server.environment} has no origin remote, so Entire can't tell which repository it is.` }
    if (!host.branch) return { ...snapshot, workspace, problem: `${path} on ${server.environment} is on no branch (detached HEAD?), so Entire has no trail to look up.` }
  } else {
    workspace.where = host.kind === 'wsl' ? `WSL ${host.distro} ${host.path}` : path
  }

  const version = await runStep(host, VERSION, signal)
  if (!version.ok) return { ...snapshot, workspace, steps: [version.step] }
  const [findings, ...results] = await Promise.all([FINDINGS, ...STEPS].map((step) => runStep(host, step, signal)))
  const data = Object.fromEntries(results.filter((result) => result.ok).map((result) => [result.step.key, result.value]))
  if (data.checkpoints) data.checkpoints = data.checkpoints.slice(0, CHECKPOINT_LIMIT)
  if (data.trail) {
    const found = findings.ok ? findings.value : null
    const base = safeRef(found?.trail?.base)
    const checkout = host.kind === 'server' ? host.remote : host
    const diff = base && checkout ? await diffStat(checkout, base, { signal }) : null
    data.trail = trailSummary(data.trail, { findings: found, diff })
  }
  return { ...snapshot, workspace, steps: [version.step, ...results.map((result) => result.step)], data }
}

function unresolved(context, via, candidates, unreachable) {
  const name = context.branch ? `${context.displayName} on ${context.branch}` : context.displayName
  const offline = unreachable.length > 0 ? ` (couldn't ask ${unreachable.join('; ')})` : ''
  if (via === 'server' && unreachable.length > 0) {
    // A server that didn't answer may hold the focused workspace under the same repo name.
    const found = candidates.length > 0 ? `${candidates.length} other ${candidates.length === 1 ? 'match' : 'matches'}, but ` : ''
    return `${name}: ${found}couldn't ask every paired server, so the focused workspace is unknown${offline}. Use ↻ once it answers.`
  }
  if (via === 'server' && candidates.length > 1) {
    // Orca names only the repo of a paired server's workspace, so its worktrees look alike.
    return `${name}: ${candidates.length} workspaces of this repository match on paired servers, and Orca doesn't tell plugins which one is focused.`
  }
  if (candidates.length > 0) {
    // Without a terminal, only branch and name identify the workspace, and many repos share "main".
    return `${name}: ${candidates.length} workspaces match it. Open a terminal in it and try again.`
  }
  return `${name}: no workspace matches it${offline}. Open a terminal in it and try again.`
}

async function runStep(host, { key, label, args, byRepo = false, optional = false, parse, summarize = (value) => value }, signal) {
  const step = { key, label, optional, ok: false }
  if (host.kind === 'server' && key !== 'version') {
    if (byRepo) args = [...args, '--repo', host.repo, '--branch', host.branch]
    else if (host.remote) host = host.remote
    // Without SSH only Entire's server is in reach; say so instead of failing.
    else return { ok: false, step: { ...step, optional: true, text: `only readable on ${host.environment}, which the plugin can't reach over SSH (${host.remoteProblem ?? 'no SSH target'})` } }
  }
  let result
  try {
    result = await runEntire(host, args, { signal })
  } catch (error) {
    return { ok: false, step: { ...step, text: error.message } }
  }
  if (result.code !== 0) return { ok: false, step: { ...step, text: explainFailure(host, result), ms: result.ms } }
  try {
    const value = parse(result.stdout)
    return { ok: true, value, step: { ...step, ok: true, text: summarize(value), ms: result.ms } }
  } catch {
    return { ok: false, step: { ...step, text: `unexpected output: ${result.stdout.slice(0, 120)}`, ms: result.ms } }
  }
}

// Entire answers a repository it doesn't track, or this desktop's login can't see, with a bare 404.
function explainFailure(host, result) {
  const line = failureLine(result)
  if (host.kind === 'server' && /repository not found/i.test(line)) return 'repository not on Entire for this computer’s login'
  // ssh exits 255 for its own failures, as opposed to the remote command's.
  if (host.kind === 'ssh' && result.code === 255) {
    const hint = /permission denied/i.test(line) ? ' Is its key in ssh-agent (ssh-add)?' : ''
    return `SSH to ${host.environment} failed: ${line}${hint}`
  }
  return line
}
