function trailKey(value) {
  return value.number + ':' + value.branch
}

// Approve and Merge, while the change is open. Merge stays off until the worker finds the change
// approved with nothing blocking (blockers in src/worker/trail.mjs); its title says why.
function actions(value) {
  var key = trailKey(value)
  var result = outcome && outcome.key === key ? el('div', 'notice outcome ' + outcome.tone, outcome.text) : null
  if (!value.open || !value.number || !value.branch) return result
  var blockers = Array.isArray(value.blockers) ? value.blockers : ['Refresh to check the merge gates']
  var row = add(
    el('div', 'actions'),
    actionButton('approve', value, { label: 'Approve', busy: 'Approving…', title: 'Approve trail #' + value.number + ' on ' + value.branch + ' in Entire' }),
    actionButton('merge', value, {
      label: 'Merge',
      busy: 'Merging…',
      title: blockers.length ? 'Merges once approved with nothing blocking:\n' + blockers.join('\n') : 'Merge ' + value.branch + ' into ' + (value.base || 'the base branch'),
      off: blockers.length > 0
    })
  )
  var why = blockers.length ? el('div', 'meta clip', 'Merge waits on: ' + blockers.join(' · ')) : null
  return add(el('div'), row, why && titled(why, blockers.join('\n')), result)
}

function actionButton(action, value, options) {
  var key = trailKey(value)
  var isArmed = armed && armed.action === action && armed.key === key
  var running = acting && acting.action === action && acting.key === key
  var label = running ? options.busy : isArmed ? 'Confirm ' + options.label.toLowerCase() + '?' : options.label
  var kind = 'action' + (action === 'merge' && !options.off ? ' go' : '') + (isArmed ? ' armed' : '')
  var button = titled(el('button', kind, label), isArmed ? 'Click again to ' + action + '. This writes to Entire.' : options.title)
  button.type = 'button'
  button.disabled = Boolean(acting) || Boolean(options.off)
  button.addEventListener('click', function () {
    if (isArmed) return act(action, value)
    armed = { action: action, key: key }
    clearTimeout(armTimer)
    armTimer = setTimeout(function () {
      armed = null
      rerender()
    }, ARM_MS)
    rerender()
  })
  return button
}

// The worker checks the trail is still the one shown for the focused workspace, runs Entire,
// reads it again and answers with { message, data }.
function act(action, value) {
  var key = trailKey(value)
  clearTimeout(armTimer)
  armed = null
  acting = { action: action, key: key }
  outcome = null
  rerender()
  orca.plugin
    .request('entire.act', { action: action, trail: value.number, branch: value.branch }, { timeoutMs: ACT_TIMEOUT_MS })
    .then(
      function (answer) {
        if (answer && answer.data) DATA = answer.data
        outcome = { key: key, tone: 'ok', text: (answer && answer.message) || 'Done.' }
      },
      function (error) {
        outcome = { key: key, tone: 'bad', text: (error && error.message) || String(error) }
      }
    )
    .then(function () {
      acting = null
      rerender()
    })
}

function mergeCard(value) {
  var state = mergeState(value)
  var card = add(el('div', 'card'), add(el('div', 'pad'), el('div', 'card-title', state.title), el('div', 'meta', state.line), actions(value)))

