/* A merge that went through bursts from where the Merge button was. The layer sits outside
   #root, so the rerender that replaces the button leaves it running. */
.sparkles {
  position: fixed;
  width: 0;
  height: 0;
  pointer-events: none;
  z-index: 10;
}
.sparkles .burst {
  position: absolute;
  left: -22px;
  top: -22px;
  width: 44px;
  height: 44px;
  border: 2px solid var(--ok);
  border-radius: 50%;
  opacity: 0;
  animation: burst 0.7s ease-out forwards;
}
.sparkles .spark {
  position: absolute;
  left: -3px;
  top: -3px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--c);
  box-shadow: 0 0 6px var(--c);
  opacity: 0;
  animation: spark 1.1s cubic-bezier(0.15, 0.75, 0.3, 1) forwards;
}
.sparkles .spark.star {
  left: -7px;
  top: -8px;
  width: auto;
  height: auto;
  background: none;
  box-shadow: none;
  color: var(--c);
  font-size: 14px;
  line-height: 1;
  text-shadow: 0 0 6px var(--c);
}
@keyframes burst {
  from {
    opacity: 0.9;
    transform: scale(0.3);
  }
  to {
    opacity: 0;
    transform: scale(2.8);
  }
}
@keyframes spark {
  0% {
    opacity: 1;
    transform: translate(0, 0) scale(0.3) rotate(0deg);
  }
  65% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translate(var(--dx), var(--dy)) scale(1) rotate(200deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  .sparkles .burst {
    animation-name: fade;
  }
  @keyframes fade {
    from {
      opacity: 0.9;
    }
    to {
      opacity: 0;
    }
  }
}

