var SPARK_COLORS = ['#2ea043', '#3fb950', '#ffd33d', '#d29922', '#58a6ff', '#f778ba', '#ffffff']

// A ring and a spray of sparks and stars from the middle of box, gone after a second and a half.
// With reduced motion, only the ring fades.
function sparkle(box) {
  if (!box) return
  var still = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches
  var layer = add(el('div', 'sparkles'), el('span', 'burst'))
  layer.style.left = box.left + box.width / 2 + 'px'
  layer.style.top = box.top + box.height / 2 + 'px'
  var count = still ? 0 : 28
  for (var i = 0; i < count; i++) {
    var angle = (i / count) * 2 * Math.PI + Math.random() * 0.35
    var reach = 28 + Math.random() * 46
    var star = i % 3 === 0
    var spark = el('span', 'spark' + (star ? ' star' : ''), star ? '✦' : null)
    // Wider than tall, like the button, and drifting up.
    spark.style.setProperty('--dx', Math.round(Math.cos(angle) * reach * 1.6) + 'px')
    spark.style.setProperty('--dy', Math.round(Math.sin(angle) * reach - 14) + 'px')
    spark.style.setProperty('--c', SPARK_COLORS[i % SPARK_COLORS.length])
    spark.style.animationDelay = Math.round(Math.random() * 140) + 'ms'
    add(layer, spark)
  }
  document.body.appendChild(layer)
  setTimeout(function () {
    if (layer.parentNode) layer.parentNode.removeChild(layer)
  }, 1500)
}

